// Incoming items from Seller_History (30 rows)
const sellers = $input.all();

// Seller_ID from the Reviews node
const targetSellerId = $('Reviews').first().json.Seller_ID;

// Find the matching seller
const match = sellers.find(
  item => item.json.Seller_ID === targetSellerId
);

if (!match) {
  throw new Error(`Seller not found: ${targetSellerId}`);
}

return [match];

